1	<!doctype html>
2	<html>
3	<head>
4	  <meta charset="utf-8">
5	  <script src="./support.js"></script>
6	</head>
7	<body>
8	<x-dc>
9	<helmet>
10	  <link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500;600&display=swap">
11	  <style>
12	    :root {
13	      --bg: oklch(98% 0.004 250);
14	      --surface: oklch(100% 0 0);
15	      --surface-2: oklch(96% 0.005 250);
16	      --border: oklch(90% 0.006 250);
17	      --text: oklch(22% 0.02 250);
18	      --text-2: oklch(48% 0.015 250);
19	      --text-3: oklch(64% 0.01 250);
20	      --accent: oklch(55% 0.16 230);
21	      --accent-dark: oklch(46% 0.16 230);
22	      --accent-2: oklch(94% 0.03 230);
23	    }
24	    * { box-sizing: border-box; }
25	    body {
26	      margin: 0;
27	      font-family: "IBM Plex Sans", -apple-system, "Segoe UI", sans-serif;
28	      color: var(--text);
29	      background: var(--bg);
30	      background-image: radial-gradient(oklch(90% 0.006 250) 1px, transparent 1px);
31	      background-size: 28px 28px;
32	    }
33	    a { color: var(--accent); text-decoration: none; }
34	    a:hover { color: var(--accent-dark); text-decoration: underline; }
35	    input {
36	      font-family: inherit;
37	      font-size: 14px;
38	      color: var(--text);
39	      background: var(--surface);
40	      border: 1px solid var(--border);
41	      border-radius: 6px;
42	      padding: 10px 12px;
43	      width: 100%;
44	    }
45	    input::placeholder { color: var(--text-3); }
46	    button {
47	      font-family: inherit;
48	      font-size: 14px;
49	      font-weight: 600;
50	      border-radius: 6px;
51	      border: none;
52	      cursor: pointer;
53	    }
54	  </style>
55	</helmet>
56	
57	<div style="width: 1440px; height: 900px; display: flex; align-items: center; justify-content: center;">
58	  <div style="width: 400px; display: flex; flex-direction: column; gap: 28px;">
59	
60	    <div style="display: flex; flex-direction: column; align-items: center; gap: 10px; text-align: center;">
61	      <svg width="36" height="36" viewBox="0 0 24 24" fill="none" stroke="var(--accent)" stroke-width="1.75">
62	        <circle cx="12" cy="12" r="9"></circle>
63	        <circle cx="12" cy="12" r="2.5" fill="var(--accent)" stroke="none"></circle>
64	        <path d="M12 3 a9 4 0 0 1 0 18 a9 4 0 0 1 0 -18" transform="rotate(35 12 12)"></path>
65	      </svg>
66	      <div style="font-size: 18px; font-weight: 700; letter-spacing: 0.01em;">Mission Control</div>
67	      <div style="font-size: 13px; color: var(--text-2);">Sign in to your organization</div>
68	    </div>
69	
70	    <div style="background: var(--surface); border: 1px solid var(--border); border-radius: 10px; padding: 28px; display: flex; flex-direction: column; gap: 18px; box-shadow: 0 1px 2px oklch(0% 0 0 / 0.04);">
71	      <div style="display: flex; flex-direction: column; gap: 6px;">
72	        <label style="font-size: 12px; font-weight: 600; color: var(--text-2);">Email</label>
73	        <input type="text" placeholder="jordan.lee@aurora-deepspace.example" value="jordan.lee@aurora-deepspace.example" />
74	      </div>
75	      <div style="display: flex; flex-direction: column; gap: 6px;">
76	        <label style="font-size: 12px; font-weight: 600; color: var(--text-2);">Password</label>
77	        <input type="text" placeholder="••••••••••" value="••••••••••" />
78	      </div>
79	      <button style="background: var(--accent); color: white; padding: 11px 16px; margin-top: 4px;">Sign in</button>
80	      <div style="font-size: 12px; color: var(--text-3);">Wrong credentials return a plain "email or password is incorrect" — never which one was wrong.</div>
81	    </div>
82	
83	    <div style="display: flex; align-items: center; gap: 10px; color: var(--text-3); font-size: 11px; text-transform: uppercase; letter-spacing: 0.06em;">
84	      <div style="flex: 1; height: 1px; background: var(--border);"></div>
85	      <div>same account, other client</div>
86	      <div style="flex: 1; height: 1px; background: var(--border);"></div>
87	    </div>
88	
89	    <div style="background: var(--surface-2); border: 1px solid var(--border); border-radius: 8px; padding: 14px 16px; display: flex; align-items: flex-start; gap: 10px;">
90	      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="var(--text-2)" stroke-width="1.75" style="flex: none; margin-top: 1px;">
91	        <rect x="3" y="4" width="18" height="16" rx="2"></rect>
92	        <path d="M7 9l3 3-3 3M13 15h4"></path>
93	      </svg>
94	      <div>
95	        <div style="font-family: 'IBM Plex Mono', monospace; font-size: 12.5px; color: var(--text);">missionctl login &lt;email&gt; &lt;password&gt;</div>
96	        <div style="font-size: 12px; color: var(--text-3); margin-top: 3px;">The CLI uses the exact same login endpoint — one credential, both clients.</div>
97	      </div>
98	    </div>
99	
100	  </div>
101	</div>
102	</x-dc>
103	</body>
104	</html>
